export const GRADE_9_FBISE_QUESTION_BANK = FBISE_9_QUESTION_BANK;

export function getGrade9FBISEQuestions(
  subject: string,
  chapters: string[] = [],
  count: number = 10,
  difficulty?: MCQDifficulty | 'mixed',
  excludeTexts: string[] = []
): MCQQuestion[] {
  const normSub = Object.keys(FBISE_9_QUESTION_BANK).find(
    (k) => k.toLowerCase() === (subject || '').trim().toLowerCase()
  );
  if (!normSub || !FBISE_9_QUESTION_BANK[normSub]) {
    return [];
  }

  const subjectBank = FBISE_9_QUESTION_BANK[normSub];
  let pool: MCQQuestion[] = [];

  if (!chapters || chapters.length === 0 || chapters.includes('Full Syllabus') || chapters.includes('All')) {
    for (const chapterQuestions of Object.values(subjectBank)) {
      pool.push(...chapterQuestions);
    }
  } else {
    for (const chapName of chapters) {
      const normChap = (chapName || '').toLowerCase().trim();
      for (const [bankChap, qs] of Object.entries(subjectBank)) {
        if (bankChap.toLowerCase().includes(normChap) || normChap.includes(bankChap.toLowerCase())) {
          pool.push(...qs);
        }
      }
    }
  }

  if (excludeTexts.length > 0) {
    const excludeSet = new Set(excludeTexts.map((t) => t.toLowerCase().trim()));
    pool = pool.filter((q) => !excludeSet.has(q.question.toLowerCase().trim()));
  }

  if (difficulty && difficulty !== 'mixed') {
    const diffFiltered = pool.filter((q) => q.difficulty === difficulty);
    if (diffFiltered.length >= count) {
      pool = diffFiltered;
    }
  }

  const shuffled = [...pool].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count);
}
